from sage.all_cmdline import *   # import sage library

_sage_const_40 = Integer(40); _sage_const_0p0 = RealNumber('0.0'); _sage_const_1 = Integer(1); _sage_const_2 = Integer(2); _sage_const_0 = Integer(0); _sage_const_1en8 = RealNumber('1e-8')# ---------------------------------------------------------
# SageMath: テイラー係数の抽出（extract_taylor_coefficient_of_Z_Y）
#
#   (h1.z)  sum_n (1/n!) ad^n_{(i/2)K_1 H_1^{(pm)}} (hatZ_mu^{(pm)})
#             = cosh(K_1) hatZ_mu^{(pm)} + i e^{-i theta} sinh(K_1) hatY_mu
#   (h1.y)  sum_n (1/n!) ad^n_{(i/2)K_1 H_1^{(pm)}} (hatY_mu)
#             = -i e^{i theta} sinh(K_1) hatZ_mu^{(pm)} + cosh(K_1) hatY_mu
#   (h2.z-) sum_n (1/n!) ad^n_{i K_2^* H_2} (hatZ_mu^{(-)})
#             = cosh(2K_2^*) hatZ_mu^{(-)} - i sinh(2K_2^*) hatY_mu
#   (h2.y)  sum_n (1/n!) ad^n_{i K_2^* H_2} (hatY_mu)
#             = i sinh(2K_2^*) hatZ_mu^{(-)} + cosh(2K_2^*) hatY_mu
#
# 対象: structured-latex extract_taylor_coefficient_of_Z_Y
# ---------------------------------------------------------
import os
_dir = os.path.dirname(os.path.abspath(__file__)) if '__file__' in dir() else '.'
load(os.path.join(_dir, '../../_shared/spin_ops.sage'))

N_TRUNC = _sage_const_40    # 級数の打ち切り次数（|K| <= 3 程度なら倍精度で収束済み）

print("=== テイラー係数の抽出（級数を n < %d で打ち切り）===" % N_TRUNC)
all_ok = True
for M in SPIN_TEST_M:
    O = SpinOps(M)
    for params in SPIN_TEST_PARAMS:
        K1v = RDF(params['K1'])
        K2s = K_star(params['K2'])
        worst = {'h1.z': _sage_const_0p0 , 'h1.y': _sage_const_0p0 , 'h2.z-': _sage_const_0p0 , 'h2.y': _sage_const_0p0 }
        for sgn in [_sage_const_1 , -_sage_const_1 ]:
            for mu in O.mu_range():
                t = O.theta(mu)
                Zh = O.Zhat(mu, sgn)
                Zm = O.Zhat(mu, -_sage_const_1 )
                Yh = O.Yhat(mu)
                X1 = CDF(I) / _sage_const_2  * K1v * O.H1(sgn)
                X2 = CDF(I) * K2s * O.H2
                acc = {k: matrix(CDF, O.d, O.d, _sage_const_0 ) for k in worst}
                term = {'h1.z': matrix(CDF, Zh), 'h1.y': matrix(CDF, Yh),
                        'h2.z-': matrix(CDF, Zm), 'h2.y': matrix(CDF, Yh)}
                for n in range(N_TRUNC):
                    f = CDF(_sage_const_1 ) / CDF(factorial(n))
                    for k in acc:
                        acc[k] = acc[k] + f * term[k]
                    term['h1.z'] = comm(X1, term['h1.z'])
                    term['h1.y'] = comm(X1, term['h1.y'])
                    term['h2.z-'] = comm(X2, term['h2.z-'])
                    term['h2.y'] = comm(X2, term['h2.y'])
                ch1, sh1 = CDF(cosh(K1v)), CDF(sinh(K1v))
                ch2, sh2 = CDF(cosh(_sage_const_2  * K2s)), CDF(sinh(_sage_const_2  * K2s))
                rhs = {
                    'h1.z': ch1 * Zh + CDF(I) * eiph(-t) * sh1 * Yh,
                    'h1.y': -CDF(I) * eiph(t) * sh1 * Zh + ch1 * Yh,
                    'h2.z-': ch2 * Zm - CDF(I) * sh2 * Yh,
                    'h2.y': CDF(I) * sh2 * Zm + ch2 * Yh,
                }
                for k in worst:
                    worst[k] = max(worst[k], opnorm(acc[k] - rhs[k]))
        print(f"M = {M}, K1 = {params['K1']}, K2 = {params['K2']} (K2* = {float(K2s):.6f}):")
        for key in ['h1.z', 'h1.y', 'h2.z-', 'h2.y']:
            all_ok = report(key, worst[key], tol=_sage_const_1en8 ) and all_ok

print("RESULT: PASS" if all_ok else "RESULT: FAIL")

